class BalancedBrackets:
    LEFT_BRACKETS = ["(", "{", "["]
    RIGHT_BRACKETS = [")", "}", "]"]
    BRACKET_PAIRS = {
        "(": ")",
        "{": "}",
        "[": "]"
    }

    def __init__(self, expr):
        self.stack = []
        self.expr = expr

    def clear_expr(self):
        self.expr = ''.join(c for c in self.expr if c in self.LEFT_BRACKETS or c in self.RIGHT_BRACKETS)

    def check_balanced_brackets(self):
        self.clear_expr()
        for bracket in self.expr:
            if not self.process_bracket(bracket):
                return False
        return not self.is_unbalanced_stack()

    def process_bracket(self, bracket):
        if bracket in self.LEFT_BRACKETS:
            self.stack.append(bracket)
            return True
        else:
            if not self.stack:
                return False
            current_bracket = self.stack.pop()
            return self.are_matching_brackets(current_bracket, bracket)

    def is_unbalanced_stack(self):
        return bool(self.stack)

    def are_matching_brackets(self, opened, closed):
        return self.BRACKET_PAIRS.get(opened) == closed
